def transform(grid):
    h, w = len(grid), len(grid[0])
    # The color key repeats the same ordered row several times; choose the
    # longest run so motif rows containing repeated 1s cannot be mistaken for it.
    runs = []
    r = 0
    while r < h:
        vals = [v for v in grid[r] if v]
        if len(vals) < 2:
            r += 1
            continue
        end = r + 1
        while end < h and [v for v in grid[end] if v] == vals:
            end += 1
        if end-r >= 2:
            runs.append((end-r, vals))
        r = end
    if not runs:
        raise ValueError('palette not found')
    # Record the exact longest repeated-row run as the palette.
    best_len, colors = max(runs, key=lambda item: item[0])
    palette_cells = set()
    for r in range(h):
        vals = [v for v in grid[r] if v]
        if vals == colors:
            end = r + 1
            while end < h and [v for v in grid[end] if v] == colors:
                end += 1
            if end-r == best_len:
                for rr in range(r, end):
                    for cc, value in enumerate(grid[rr]):
                        if value:
                            palette_cells.add((rr,cc))
                break
    pts = [(r,c) for r in range(h) for c in range(w)
           if grid[r][c] == 1 and (r,c) not in palette_cells]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    stencil = [[1 if grid[r][c] == 1 else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    sh, sw = len(stencil), len(stencil[0])
    out = [[0]*w for _ in range(h)]
    start = r0 - colors.index(1)*sh
    for i, color in enumerate(colors):
        for dr in range(sh):
            for dc in range(sw):
                if stencil[dr][dc]:
                    out[start+i*sh+dr][c0+dc] = color
    return out
